	memset(out, 0, TCPBP_FIXED_LEN);
	{ uint16_t w = htons(b->src_port); memcpy(out + 0, &w, 2); }
	{ uint16_t w = htons(b->dst_port); memcpy(out + 2, &w, 2); }
	{ uint32_t w = htonl(b->seq_no); memcpy(out + 4, &w, 4); }
	{ uint32_t w = htonl(b->ack_seq); memcpy(out + 8, &w, 4); }
	out[13] = b->flags;
	{ uint16_t w = htons(b->window); memcpy(out + 14, &w, 2); }
	{ uint16_t w = htons(b->urg_ptr); memcpy(out + 18, &w, 2); }
	memcpy(out + TCPBP_FIXED_LEN, b->__opt, b->__opt_len);
	hdr_len = (uint16_t)(TCPBP_FIXED_LEN + b->__opt_len);
	/* hdrlen4_t: a property of the layout, so the compiler fills it */
	out[12] = (uint8_t)((hdr_len / 4) << 4);
	return hdr_len;
